import { createServer } from 'node:http';
import { loadBooks, addBook, getBook, finishBook } from './store.mjs';

const PORT = process.env.PORT || 3000;

function escapeHtml(s) {
  return String(s)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; color: #222; line-height: 1.5; }
  h1, h2 { line-height: 1.2; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { padding: 0.6rem 0; border-bottom: 1px solid #eee; display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; }
  .author { color: #666; }
  form.inline { display: inline; }
  label { display: block; margin-top: 0.8rem; font-weight: 600; }
  input[type="text"], textarea { width: 100%; padding: 0.4rem; font: inherit; box-sizing: border-box; }
  button { margin-top: 0.8rem; padding: 0.4rem 0.9rem; font: inherit; cursor: pointer; }
  .muted { color: #888; }
  a { color: #0a5; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: 0.8rem; border-radius: 4px; }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function bookListItem(book, { showFinishButton }) {
  const finish = showFinishButton
    ? `<form class="inline" method="post" action="/books/${book.id}/finish"><button>Finished it</button></form>`
    : '';
  return `<li>
    <span><a href="/books/${book.id}">${escapeHtml(book.title)}</a>
    <span class="author">by ${escapeHtml(book.author)}</span></span>
    ${finish}
  </li>`;
}

async function homePage() {
  const books = await loadBooks();
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);

  const readingHtml = reading.length
    ? `<ul class="books">${reading.map((b) => bookListItem(b, { showFinishButton: true })).join('')}</ul>`
    : '<p class="muted">Nothing on the go right now.</p>';
  const finishedHtml = finished.length
    ? `<ul class="books">${finished.map((b) => bookListItem(b, { showFinishButton: false })).join('')}</ul>`
    : '<p class="muted">No finished books yet.</p>';

  return page('My books', `
    <h1>My books</h1>
    <h2>Currently reading</h2>
    ${readingHtml}
    <h2>Finished</h2>
    ${finishedHtml}
    <h2>Add a book</h2>
    <form method="post" action="/books">
      <label for="title">Title</label>
      <input type="text" id="title" name="title" required>
      <label for="author">Author</label>
      <input type="text" id="author" name="author" required>
      <label for="notes">Notes</label>
      <textarea id="notes" name="notes" rows="4"></textarea>
      <button>Add book</button>
    </form>
  `);
}

function bookPage(book) {
  const status = book.finished ? 'Finished' : 'Currently reading';
  const finishForm = book.finished
    ? ''
    : `<form method="post" action="/books/${book.id}/finish"><button>Finished it</button></form>`;
  const notes = book.notes
    ? `<div class="notes">${escapeHtml(book.notes)}</div>`
    : '<p class="muted">No notes yet.</p>';
  return page(book.title, `
    <p><a href="/">&larr; All books</a></p>
    <h1>${escapeHtml(book.title)}</h1>
    <p class="author">by ${escapeHtml(book.author)} &middot; ${status}</p>
    <h2>Notes</h2>
    ${notes}
    ${finishForm}
  `);
}

function send(res, status, html) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

async function readForm(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 100_000) throw new Error('Request body too large');
  }
  return new URLSearchParams(body);
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
    const path = url.pathname;

    if (req.method === 'GET' && path === '/') {
      return send(res, 200, await homePage());
    }

    if (req.method === 'POST' && path === '/books') {
      const form = await readForm(req);
      const title = (form.get('title') ?? '').trim();
      const author = (form.get('author') ?? '').trim();
      if (!title || !author) {
        return send(res, 400, page('Missing fields', '<p>Title and author are required. <a href="/">Back</a></p>'));
      }
      await addBook({ title, author, notes: form.get('notes') ?? '' });
      return redirect(res, '/');
    }

    const detailMatch = path.match(/^\/books\/([0-9a-f-]+)$/);
    if (req.method === 'GET' && detailMatch) {
      const book = await getBook(detailMatch[1]);
      if (!book) return send(res, 404, page('Not found', '<p>Book not found. <a href="/">Back</a></p>'));
      return send(res, 200, bookPage(book));
    }

    const finishMatch = path.match(/^\/books\/([0-9a-f-]+)\/finish$/);
    if (req.method === 'POST' && finishMatch) {
      const book = await finishBook(finishMatch[1]);
      if (!book) return send(res, 404, page('Not found', '<p>Book not found. <a href="/">Back</a></p>'));
      return redirect(res, '/');
    }

    send(res, 404, page('Not found', '<p>Page not found. <a href="/">Back</a></p>'));
  } catch (err) {
    console.error(err);
    send(res, 500, page('Error', '<p>Something went wrong. <a href="/">Back</a></p>'));
  }
});

server.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`);
});

