import { beforeEach, expect, test } from 'vitest';
import { rm } from 'node:fs/promises';
import { loadBooks, addBook, getBook, finishBook } from './store.mjs';

beforeEach(async () => {
  await rm(new URL('./books.json', import.meta.url), { force: true });
});

test('starts empty when no data file exists', async () => {
  expect(await loadBooks()).toEqual([]);
});

test('adds a book and persists it', async () => {
  const book = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.' });
  expect(book.id).toBeTruthy();
  expect(book.finished).toBe(false);
  expect(await getBook(book.id)).toEqual(book);
});

test('marks a book finished', async () => {
  const book = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: '' });
  const finished = await finishBook(book.id);
  expect(finished.finished).toBe(true);
  expect(finished.finishedAt).toBeTruthy();
  expect((await getBook(book.id)).finished).toBe(true);
});

test('returns null for unknown ids', async () => {
  expect(await getBook('nope')).toBeNull();
  expect(await finishBook('nope')).toBeNull();
});

